import { createHash } from 'node:crypto';
import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import type pg from 'pg';
import type { Executor } from './client';
import { localities } from './schema';

// Belgian localities of GeoNames (ADR 0017, decision D6): a derived file versioned next to the
// migrations, regenerated by `pnpm geonames`, and loaded by the migration after checking its
// fingerprint. Public data, common to every account: no user_id, no row-level security.

/** Where the file lives, inside the migrations folder (copied as is into the image). */
export const LOCALITIES_FILE = join('data', 'localities.tsv');
/** Written by `pnpm geonames`: the migration refuses any other file. */
export const LOCALITIES_SHA256 = '5f8b176688d2923704b1e5789c5e1b31f4d55da65b69b583e6713a7e140805f9';
export const LOCALITIES_DATASET = 'localities';

export interface LocalityRow {
  id: number;
  name: string;
  names: string[];
  postalCodes: string[];
  latitude: number;
  longitude: number;
  region: string;
  province: string;
}

export const sha256Of = (text: string) => createHash('sha256').update(text, 'utf8').digest('hex');

/** The lines of the file, its header and comments left out. */
export function parseLocalities(text: string): LocalityRow[] {
  const result: LocalityRow[] = [];
  for (const line of text.split('\n')) {
    if (line === '' || line.startsWith('#') || line.startsWith('id\t')) continue;
    const [id, name, names, codes, latitude, longitude, region, province] = line.split('\t');
    const row = {
      id: Number(id),
      name: name ?? '',
      names: names ? names.split('|') : [],
      postalCodes: codes ? codes.split(',') : [],
      latitude: Number(latitude),
      longitude: Number(longitude),
      region: region ?? '',
      province: province ?? '',
    };
    if (
      !Number.isInteger(row.id) ||
      row.name === '' ||
      row.postalCodes.length === 0 ||
      !Number.isFinite(row.latitude) ||
      !Number.isFinite(row.longitude)
    ) {
      throw new Error(`malformed localities line: ${line.slice(0, 80)}`);
    }
    result.push(row);
  }
  return result;
}

const CHUNK = 500;

/**
 * Loads the localities file when the database holds another version of it. The file must match
 * its fingerprint: an altered or truncated file stops the migration. Skipped before migration
 * 0010 has created the table.
 */
export async function loadLocalities(
  client: pg.Client,
  migrationsFolder: string,
  expected: string = LOCALITIES_SHA256,
): Promise<{ loaded: boolean; rows: number }> {
  const table = await client.query<{ exists: string | null }>(
    "select to_regclass('public.locality')::text as exists",
  );
  if (!table.rows[0]?.exists) return { loaded: false, rows: 0 };
  const text = await readFile(join(migrationsFolder, LOCALITIES_FILE), 'utf8');
  const digest = sha256Of(text);
  if (digest !== expected) {
    throw new Error('the localities file does not match its fingerprint (run pnpm geonames)');
  }
  const current = await client.query<{ sha256: string }>(
    'select sha256 from dataset where name = $1',
    [LOCALITIES_DATASET],
  );
  if (current.rows[0]?.sha256 === digest) return { loaded: false, rows: 0 };
  const localities = parseLocalities(text);
  await client.query('begin');
  try {
    await client.query('delete from locality');
    for (let index = 0; index < localities.length; index += CHUNK) {
      const chunk = localities.slice(index, index + CHUNK);
      const values: unknown[] = [];
      const tuples = chunk.map((row, offset) => {
        const base = offset * 8;
        values.push(
          row.id,
          row.name,
          row.names,
          row.postalCodes,
          row.latitude,
          row.longitude,
          row.region,
          row.province,
        );
        return `(${Array.from({ length: 8 }, (_, column) => `$${base + column + 1}`).join(', ')})`;
      });
      await client.query(
        `insert into locality (id, name, names, postal_codes, latitude, longitude, region, province) values ${tuples.join(', ')}`,
        values,
      );
    }
    await client.query(
      `insert into dataset (name, sha256, rows, loaded_at) values ($1, $2, $3, now())
       on conflict (name) do update set sha256 = excluded.sha256, rows = excluded.rows, loaded_at = now()`,
      [LOCALITIES_DATASET, digest, localities.length],
    );
    await client.query('commit');
  } catch (error) {
    await client.query('rollback');
    throw error;
  }
  return { loaded: true, rows: localities.length };
}

/** Every locality, as the gazetteer of packages/collect reads them. */
export async function readLocalities(db: Executor): Promise<LocalityRow[]> {
  const rows = await db.select().from(localities);
  return rows.map((row) => ({
    id: row.id,
    name: row.name,
    names: row.names,
    postalCodes: row.postalCodes,
    latitude: row.latitude,
    longitude: row.longitude,
    region: row.region,
    province: row.province,
  }));
}
